import json
import re
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Set

from langchain_ollama import OllamaEmbeddings
from langchain_chroma import Chroma
from langchain_core.documents import Document

from config import Config
from .preprocess import CHUNKS_PATH


_STABLE_CHUNK_ID = re.compile(r".+_chunk_\d+")


def load_chunks() -> List[Dict]:
    """Load chunk records from the JSONL file generated by preprocessing."""
    chunks = []
    with CHUNKS_PATH.open("r", encoding="utf-8") as f:
        for line in f:
            if line.strip():
                chunks.append(json.loads(line))
    return chunks


def _chunk_id(chunk: Dict) -> str:
    chunk_id = chunk.get("id")
    if not isinstance(chunk_id, str) or not chunk_id:
        raise ValueError("Every chunk must have a non-empty stable string id.")
    return chunk_id


def build_vectorstore(
    force: bool = False, chunks: Optional[Sequence[Dict]] = None
) -> Set[str]:
    """Synchronize the persistent Chroma collection with the processed chunks.

    Existing Chroma records with legacy auto-generated IDs are left untouched and
    cause synchronization to fail. They require an explicit migration or rebuild.
    """
    del force  # Reprocessing data must not implicitly erase a persistent collection.

    persist_dir = Path(Config.CHROMA_PERSIST_DIR)
    persist_dir.mkdir(parents=True, exist_ok=True)

    chunks = list(chunks) if chunks is not None else load_chunks()
    chunk_ids = [_chunk_id(chunk) for chunk in chunks]
    if len(chunk_ids) != len(set(chunk_ids)):
        raise ValueError("Processed chunks contain duplicate stable IDs.")

    embedding = OllamaEmbeddings(
        base_url=Config.OLLAMA_BASE_URL, model=Config.OLLAMA_EMBEDDING_MODEL
    )
    vectorstore = Chroma(
        persist_directory=str(persist_dir),
        embedding_function=embedding,
        collection_name=Config.CHROMA_COLLECTION_NAME,
    )
    collection = vectorstore._collection
    existing_ids = set(collection.get(include=[])["ids"])
    legacy_ids = {
        record_id
        for record_id in existing_ids
        if not _STABLE_CHUNK_ID.fullmatch(record_id)
    }
    if legacy_ids:
        raise RuntimeError(
            "Chroma contains records with legacy or unmanaged IDs; no data was "
            "changed. Explicitly migrate or rebuild this collection before "
            f"synchronizing it ({len(legacy_ids)} unmanaged records found)."
        )

    documents = [
        Document(
            page_content=chunk["content"],
            metadata={"title": chunk.get("title"), **chunk.get("metadata", {})},
        )
        for chunk in chunks
    ]
    batch_size = Config.EMBEDDING_BATCH_SIZE
    for start in range(0, len(documents), batch_size):
        end = min(start + batch_size, len(documents))
        vectorstore.add_documents(documents[start:end], ids=chunk_ids[start:end])
        print(f"✅ Indexed Chroma batch {start // batch_size + 1}")

    stale_ids = existing_ids - set(chunk_ids)
    if stale_ids:
        print(f"🧹 Removing {len(stale_ids)} stale stable-ID Chroma records.")
        collection.delete(ids=sorted(stale_ids))

    synchronized_ids = set(collection.get(include=[])["ids"])
    expected_ids = set(chunk_ids)
    if synchronized_ids != expected_ids:
        raise RuntimeError(
            "Chroma synchronization produced an unexpected ID set "
            f"(expected {len(expected_ids)}, found {len(synchronized_ids)})."
        )

    print(
        f"🎉 Chroma collection '{Config.CHROMA_COLLECTION_NAME}' synchronized "
        f"with {len(synchronized_ids)} chunks at {persist_dir}."
    )
    return synchronized_ids
